package il.transit.core

import il.transit.core.calendar.DayKind
import il.transit.core.calendar.Holiday
import il.transit.core.calendar.Holidays
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.time.DayOfWeek
import java.time.LocalDate

/**
 * The bundled holiday table (Phase 10 D3), generated by `tools/gen_holidays.py`. Pinned dates
 * are Israel's, from hebcal.com (Jewish holidays, Israel, 2026–2031; checked 2026-10-12). The
 * festival days of every year also match pyluach (`gen_holidays.py --check`).
 */
class HolidaysTest {
    private fun d(y: Int, m: Int, day: Int) = LocalDate.of(y, m, day)

    @Test fun `pinned dates - hebcal`() {
        assertEquals(Holiday.YOM_KIPPUR, Holidays.holiday(d(2026, 9, 21))) // Mon
        assertEquals(Holiday.PESACH_1, Holidays.holiday(d(2027, 4, 22))) // Thu
        assertEquals(Holiday.ROSH_HASHANA_1, Holidays.holiday(d(2026, 9, 12))) // Sat
        assertEquals(Holiday.ROSH_HASHANA_2, Holidays.holiday(d(2026, 9, 13))) // Sun
        assertEquals(Holiday.SUKKOT, Holidays.holiday(d(2026, 9, 26))) // Sat
        assertEquals(Holiday.SHMINI_ATZERET, Holidays.holiday(d(2026, 10, 3))) // Sat (Simchat Torah, one day in Israel)
        assertEquals(Holiday.PESACH_1, Holidays.holiday(d(2026, 4, 2))) // Thu
        assertEquals(Holiday.PESACH_7, Holidays.holiday(d(2026, 4, 8))) // Wed (one day: no Pesach VIII in Israel)
        assertEquals(Holiday.SHAVUOT, Holidays.holiday(d(2026, 5, 22))) // Fri
        assertEquals(Holiday.SHAVUOT, Holidays.holiday(d(2027, 6, 11))) // Fri
        assertEquals(Holiday.YOM_KIPPUR, Holidays.holiday(d(2027, 10, 11))) // Mon
        assertEquals(Holiday.PESACH_1, Holidays.holiday(d(2028, 4, 11))) // Tue
        assertEquals(Holiday.ROSH_HASHANA_1, Holidays.holiday(d(2031, 9, 18))) // Thu, the table's last autumn
        assertNull(Holidays.holiday(d(2026, 4, 10))) // no Pesach VIII in Israel
        assertNull(Holidays.holiday(d(2026, 5, 23))) // no second day of Shavuot either
    }

    @Test fun `moving rules - Yom HaShoah, Yom HaZikaron, Yom HaAtzmaut`() {
        // Yom HaAtzmaut 5 Iyar on a Wednesday stays (2026: Wed 22 Apr, Zikaron Tue 21 Apr).
        assertEquals(Holiday.YOM_HAATZMAUT, Holidays.holiday(d(2026, 4, 22)))
        assertEquals(Holiday.YOM_HAZIKARON, Holidays.holiday(d(2026, 4, 21)))
        // 5 Iyar on a Monday moves to Tuesday (2028: Mon 1 May → Tue 2 May; Zikaron Mon 1 May).
        assertEquals(Holiday.YOM_HAATZMAUT, Holidays.holiday(d(2028, 5, 2)))
        assertEquals(Holiday.YOM_HAZIKARON, Holidays.holiday(d(2028, 5, 1)))
        // 5 Iyar on a Friday moves back to Thursday (2029: Fri 20 Apr → Thu 19 Apr; Zikaron Wed 18 Apr).
        assertEquals(Holiday.YOM_HAATZMAUT, Holidays.holiday(d(2029, 4, 19)))
        assertEquals(Holiday.YOM_HAZIKARON, Holidays.holiday(d(2029, 4, 18)))
        assertNull(Holidays.holiday(d(2029, 4, 20)))
        // 2031: Mon 28 Apr → Tue 29 Apr.
        assertEquals(Holiday.YOM_HAATZMAUT, Holidays.holiday(d(2031, 4, 29)))
        // Yom HaShoah 27 Nisan: Sunday → Monday (2028: Sun 23 Apr → Mon 24 Apr); a Tuesday stays (2026: 14 Apr).
        assertEquals(Holiday.YOM_HASHOAH, Holidays.holiday(d(2028, 4, 24)))
        assertNull(Holidays.holiday(d(2028, 4, 23)))
        assertEquals(Holiday.YOM_HASHOAH, Holidays.holiday(d(2026, 4, 14)))
        // Every memorial and independence day of the table is on a day the rules allow.
        for ((date, h) in all()) when (h) {
            Holiday.YOM_HAATZMAUT -> assertTrue("$date", date.dayOfWeek in setOf(DayOfWeek.TUESDAY, DayOfWeek.WEDNESDAY, DayOfWeek.THURSDAY))
            Holiday.YOM_HASHOAH -> assertFalse("$date", date.dayOfWeek in setOf(DayOfWeek.FRIDAY, DayOfWeek.SATURDAY, DayOfWeek.SUNDAY))
            else -> Unit
        }
    }

    @Test fun `every year has every holiday once, and the right number of Chol HaMoed days`() {
        val once = Holiday.entries - Holiday.CHOL_HAMOED_PESACH - Holiday.CHOL_HAMOED_SUKKOT
        for (year in Holidays.FIRST_YEAR..Holidays.LAST_YEAR) {
            val days = all().filter { it.first.year == year }.map { it.second }
            for (h in once) assertEquals("$h in $year", 1, days.count { it == h })
            assertEquals("Chol HaMoed Pesach $year", 5, days.count { it == Holiday.CHOL_HAMOED_PESACH })
            assertEquals("Chol HaMoed Sukkot $year", 6, days.count { it == Holiday.CHOL_HAMOED_SUKKOT }) // incl. Hoshana Rabba
        }
    }

    @Test fun `sunset days fall on the right civil day - the eve is the day before`() {
        // Yom Kippur starts on the evening of Sun 20 Sep 2026: that civil day is its eve.
        val eve = Holidays.day(d(2026, 9, 20))!!
        assertEquals(DayKind.YOM_KIPPUR_EVE, eve.kind)
        assertEquals(Holiday.YOM_KIPPUR, eve.holiday)
        assertEquals(DayKind.NO_SERVICE, Holidays.day(d(2026, 9, 21))!!.kind)
        assertNull(Holidays.day(d(2026, 9, 22))) // service again from the evening of the 21st: an ordinary day
        // Erev Pesach 2027 (Wed 21 Apr) is an eve; Rosh Hashana 1 is no-service even though day 2 follows.
        assertEquals(DayKind.EVE, Holidays.day(d(2027, 4, 21))!!.kind)
        assertEquals(DayKind.NO_SERVICE, Holidays.day(d(2026, 9, 12))!!.kind)
        // Hoshana Rabba (Chol HaMoed and the eve of Shmini Atzeret) is an eve; Chol HaMoed alone is reduced.
        assertEquals(DayKind.EVE, Holidays.day(d(2026, 10, 2))!!.kind)
        assertEquals(Holiday.SHMINI_ATZERET, Holidays.day(d(2026, 10, 2))!!.holiday)
        assertEquals(DayKind.REDUCED, Holidays.day(d(2026, 9, 29))!!.kind)
        assertEquals(DayKind.REDUCED, Holidays.day(d(2026, 4, 22))!!.kind) // Yom HaAtzmaut
        assertNull(Holidays.day(d(2026, 4, 21))) // Yom HaZikaron: transport as usual
        assertNull(Holidays.day(d(2026, 10, 13))) // an ordinary Tuesday
    }

    @Test fun `rest days and short days`() {
        assertTrue(Holidays.restDay(d(2026, 10, 17))) // Saturday
        assertTrue(Holidays.restDay(d(2027, 4, 22))) // Pesach, a Thursday
        assertFalse(Holidays.restDay(d(2027, 4, 23))) // Friday after: a short day
        assertTrue(Holidays.shortDay(d(2027, 4, 23)))
        assertTrue(Holidays.shortDay(d(2027, 4, 21))) // Erev Pesach
        assertFalse(Holidays.shortDay(d(2026, 10, 13)))
    }

    @Test fun `out of date from the table's last year`() {
        assertEquals(2031, Holidays.LAST_YEAR)
        assertFalse(Holidays.outOfDate(d(2030, 12, 31)))
        assertTrue(Holidays.outOfDate(d(2031, 1, 1)))
        assertTrue(Holidays.covers(d(2026, 1, 1)))
        assertFalse(Holidays.covers(d(2032, 4, 1)))
    }

    private fun all() = (0L..java.time.temporal.ChronoUnit.DAYS.between(d(2026, 1, 1), d(2031, 12, 31)))
        .map { d(2026, 1, 1).plusDays(it) }
        .mapNotNull { day -> Holidays.holiday(day)?.let { day to it } }
}
